const jobs = [
  { id: "build", priority: 2 },
  { id: "deploy", priority: 1 },
  { id: "test", priority: 2 }
];

function findById(jobs, id) {
  for (const j of jobs) if (j.id === id) return j;
  return null;
}

function findSmallest(jobs) {
  let best = null;
  for (const j of jobs) if (best === null || j.priority < best.priority) best = j;
  return best;
}

console.log(findById(jobs, "test"));
console.log(findSmallest(jobs));
console.log("both walked all", jobs.length, "jobs to answer one question");

