function heapPush(heap, value) {
  heap.push(value);
  var i = heap.length - 1;
  while (i > 0) {
    var parent = (i - 1) >> 1;
    if (heap[parent] <= heap[i]) break;
    var t = heap[i]; heap[i] = heap[parent]; heap[parent] = t;
    i = parent;
  }
  return heap;
}

