const heap = [
  { seq: 0, id: "p" },
  { seq: 1, id: "q" },
  { seq: 2, id: "r" }
];
const cancelled = { p: true };

function nextRunnable(heap, cancelled) {
  let discarded = 0;
  while (heap.length) {
    const entry = heap.shift();
    if (cancelled[entry.id]) { discarded++; continue; }
    return { id: entry.id, discarded };
  }
  return { id: null, discarded };
}

console.log("entries held:", heap.length, "runnable jobs:", heap.length - 1);
console.log(nextRunnable(heap, cancelled));
