function nextLive(queue, cancelled) {
  var dead = Object.create(null);
  for (var i = 0; i < cancelled.length; i++) dead[cancelled[i]] = true;
  var discarded = 0;
  for (var j = 0; j < queue.length; j++) {
    if (!dead[queue[j]]) return { id: queue[j], discarded: discarded };
    discarded++;
  }
  return { id: null, discarded: discarded };
}

