function makeHistory(capacity) {
  return { capacity, head: null, tail: null, nodes: Object.create(null), size: 0 };
}

function detach(h, node) {
  if (node.prev) node.prev.next = node.next; else h.head = node.next;
  if (node.next) node.next.prev = node.prev; else h.tail = node.prev;
  node.prev = null; node.next = null;
}

function touch(h, id) {
  let node = h.nodes[id];
  if (node) detach(h, node);
  else { node = { id, prev: null, next: null }; h.nodes[id] = node; h.size++; }
  node.next = h.head;
  if (h.head) h.head.prev = node;
  h.head = node;
  if (!h.tail) h.tail = node;
  if (h.size > h.capacity) {
    const drop = h.tail;
    detach(h, drop);
    delete h.nodes[drop.id];
    h.size--;
  }
  return h;
}

function list(h) {
  const out = [];
  for (let n = h.head; n; n = n.next) out.push(n.id);
  return out;
}

const h = makeHistory(3);
for (const id of ["a", "b", "c", "a", "d"]) { touch(h, id); console.log(id, "->", list(h)); }

